fn look_for_min(a: &[i32], i: usize) -> usize {
    let mut min_index = i; // Start with the initial index
    let mut min_value = a[i]; // Initialize the minimum value with the value at the start index

    // Iterate through the array from the start index to the end
    for j in i..a.len() {
        if a[j] < min_value {
            min_value = a[j]; // Update the minimum value
            min_index = j; // Update the index of the minimum value
        }
    }

    min_index // Return the index of the minimum element
}

